"use client";

import { useEffect, useMemo, useState } from "react";
import AppShell from "@/components/Navbar";
import { api } from "@/lib/api";

type Day = "Monday" | "Tuesday" | "Wednesday" | "Thursday" | "Friday" | "Saturday";

interface ScheduleEntry {
  id: number;
  request_id?: number;
  section_name?: string;
  course_code?: string;
  course_title?: string;
  instructor_name?: string;
  room_number?: string;
  building?: string;
  day_of_week?: Day;
  time_start?: string;
  time_end?: string;
  expected_students?: number;
  room_capacity?: number;
  is_active?: boolean;
}

interface ScheduleResponse {
  success: boolean;
  message: string;
  data: ScheduleEntry[];
  meta: { total: number; page: number; per_page: number };
}

const DAYS: Day[] = ["Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday"];

export default function AdminSchedulePage() {
  const [rows, setRows] = useState<ScheduleEntry[]>([]);
  const [meta, setMeta] = useState({ total: 0, page: 1, per_page: 15 });
  const [page, setPage] = useState(1);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [view, setView] = useState<"list" | "calendar">("list");
  const [dayFilter, setDayFilter] = useState<Day | "All">("All");
  const [statusFilter, setStatusFilter] = useState<"all" | "active" | "released">("active");
  const [busyId, setBusyId] = useState<number | null>(null);

  async function load() {
    try {
      setLoading(true);
      setError(null);
      const res = await api.get<ScheduleResponse>(`/admin/schedule?page=${page}`);
      setRows(res.data ?? []);
      setMeta(res.meta ?? { total: 0, page, per_page: 15 });
    } catch (e) {
      setError(e instanceof Error ? e.message : "Failed to load schedule.");
    } finally {
      setLoading(false);
    }
  }

  useEffect(() => { load(); }, [page]);

  async function releaseBooking(id: number) {
    try {
      setBusyId(id);
      setError(null);
      await api.post(`/admin/schedule/${id}/release`, {});
      await load();
    } catch (e) {
      setError(e instanceof Error ? e.message : "Failed to release booking.");
    } finally {
      setBusyId(null);
    }
  }

  const filtered = useMemo(() => {
    return rows.filter((r) => {
      if (dayFilter !== "All" && r.day_of_week !== dayFilter) return false;
      if (statusFilter === "active" && !r.is_active) return false;
      if (statusFilter === "released" && r.is_active) return false;
      return true;
    });
  }, [rows, dayFilter, statusFilter]);

  const totalPages = Math.max(1, Math.ceil(meta.total / meta.per_page));

  return (
    <AppShell role="admin" userName="Admin" pageTitle="Master Schedule">
      <div className="space-y-4">
        <div className="flex flex-wrap items-center justify-between gap-3">
          <div>
            <h1 className="text-xl font-semibold">Master Schedule</h1>
            <p className="text-sm" style={{ color: "var(--color-text-secondary)" }}>All confirmed room bookings</p>
          </div>
          <div className="flex gap-2">
            <button className={`btn btn-sm ${view === "list" ? "btn-primary" : "btn-outline"}`} onClick={() => setView("list")}>List</button>
            <button className={`btn btn-sm ${view === "calendar" ? "btn-primary" : "btn-outline"}`} onClick={() => setView("calendar")}>Calendar</button>
          </div>
        </div>

        <div className="card card-body flex flex-wrap gap-3">
          <select value={statusFilter} onChange={(e) => setStatusFilter(e.target.value as "all" | "active" | "released")}>
            <option value="all">All Status</option>
            <option value="active">Active</option>
            <option value="released">Released</option>
          </select>
          <select value={dayFilter} onChange={(e) => setDayFilter(e.target.value as Day | "All")}>
            <option value="All">All Days</option>
            {DAYS.map((d) => <option key={d} value={d}>{d}</option>)}
          </select>
          <span className="text-xs ml-auto" style={{ color: "var(--color-text-muted)" }}>{filtered.length} of {rows.length} loaded</span>
        </div>

        {error && <div className="rounded-lg border px-3 py-2 text-[12px]" style={{ borderColor: "#fecaca", background: "#fff1f2", color: "#9f1239" }}>{error}</div>}

        {view === "list" ? (
          <div className="card overflow-x-auto">
            <table className="table-base">
              <thead>
                <tr><th>Course</th><th>Section</th><th>Instructor</th><th>Room</th><th>Day/Time</th><th>Status</th><th></th></tr>
              </thead>
              <tbody>
                {loading ? (
                  <tr><td colSpan={7} className="text-center py-10">Loading...</td></tr>
                ) : filtered.length === 0 ? (
                  <tr><td colSpan={7} className="text-center py-10">No schedule entries found.</td></tr>
                ) : (
                  filtered.map((e) => (
                    <tr key={e.id}>
                      <td>{e.course_code ?? "N/A"} <span className="text-xs" style={{ color: "var(--color-text-muted)" }}>{e.course_title ? `- ${e.course_title}` : ""}</span></td>
                      <td>{e.section_name ?? "N/A"}</td>
                      <td>{e.instructor_name ?? "N/A"}</td>
                      <td>{e.room_number ?? "TBA"} <span className="text-xs" style={{ color: "var(--color-text-muted)" }}>{e.building ?? ""}</span></td>
                      <td>{e.day_of_week ?? ""} {e.time_start?.slice(0, 5)}-{e.time_end?.slice(0, 5)}</td>
                      <td><span className={`badge ${e.is_active ? "badge-green" : "badge-gray"}`}>{e.is_active ? "Active" : "Released"}</span></td>
                      <td>
                        {e.is_active ? (
                          <button className="btn btn-sm btn-outline" disabled={busyId === e.id} onClick={() => releaseBooking(e.id)}>
                            {busyId === e.id ? "..." : "Release"}
                          </button>
                        ) : null}
                      </td>
                    </tr>
                  ))
                )}
              </tbody>
            </table>
          </div>
        ) : (
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-3">
            {filtered.map((e) => (
              <div key={e.id} className="card card-body">
                <p className="text-sm font-semibold">{e.course_code ?? "N/A"}</p>
                <p className="text-xs" style={{ color: "var(--color-text-secondary)" }}>{e.section_name ?? "N/A"} · {e.instructor_name ?? "N/A"}</p>
                <p className="text-xs mt-1">{e.day_of_week ?? ""} {e.time_start?.slice(0, 5)}-{e.time_end?.slice(0, 5)}</p>
                <p className="text-xs">{e.room_number ?? "TBA"} · {e.building ?? ""}</p>
                <div className="mt-2 flex items-center justify-between">
                  <span className={`badge ${e.is_active ? "badge-green" : "badge-gray"}`}>{e.is_active ? "Active" : "Released"}</span>
                  {e.is_active ? <button className="btn btn-sm btn-outline" onClick={() => releaseBooking(e.id)}>Release</button> : null}
                </div>
              </div>
            ))}
            {!loading && filtered.length === 0 && <div className="card card-body">No schedule entries found.</div>}
          </div>
        )}

        <div className="flex items-center justify-between">
          <p className="text-xs" style={{ color: "var(--color-text-muted)" }}>Page {meta.page} of {totalPages}</p>
          <div className="flex gap-2">
            <button className="btn btn-outline btn-sm" disabled={page <= 1} onClick={() => setPage((p) => Math.max(1, p - 1))}>Previous</button>
            <button className="btn btn-outline btn-sm" disabled={page >= totalPages} onClick={() => setPage((p) => Math.min(totalPages, p + 1))}>Next</button>
          </div>
        </div>
      </div>
    </AppShell>
  );
}
